// 自定义类加载器：只重写 findClass，保持双亲委派
public class PluginClassLoader extends ClassLoader {
    private final Path dir;
    public PluginClassLoader(Path dir, ClassLoader parent) { super(parent); this.dir = dir; }

    @Override
    protected Class<?> findClass(String name) throws ClassNotFoundException {
        try {
            byte[] bytes = Files.readAllBytes(dir.resolve(name.replace('.', '/') + ".class"));
            return defineClass(name, bytes, 0, bytes.length);
        } catch (IOException e) { throw new ClassNotFoundException(name, e); }
    }
}
// loadClass 默认逻辑：已加载? → parent.loadClass → findClass
// 若重写 loadClass 先自己加载，就是打破双亲委派（Tomcat 的做法）

