// Netty 典型泄漏：读到 ByteBuf 后没有 release
public void channelRead(ChannelHandlerContext ctx, Object msg) {
    ByteBuf buf = (ByteBuf) msg;
    try {
        handle(buf);
    } finally {
        ReferenceCountUtil.release(buf);   // 不释放会导致池化直接内存泄漏
    }
}

// 逃逸分析：point 不逃逸 → 标量替换，不在堆上分配
public int distance(int x, int y) {
    Point point = new Point(x, y);         // JIT 后被拆成局部变量 x、y
    return point.x * point.x + point.y * point.y;
}

