// 可数循环：JIT 可能不在回边放安全点，导致其他线程等它进入安全点
static int sum(int[] arr) {
    int s = 0;
    for (int i = 0; i < arr.length; i++) {   // int 索引 → 可数循环
        s += heavyButInlined(arr[i]);
    }
    return s;
}

